const OTP_LENGTH = 6;
const RESEND_COOLDOWN_SECONDS = 30;
const SIMULATED_LATENCY_MS = 550;

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function generateDummyOtp() {
  return Array.from({ length: OTP_LENGTH }, () => Math.floor(Math.random() * 10)).join("");
}

function maskWhatsappNumber(number) {
  const digits = number.replace(/\D/g, "");
  const lastFour = digits.slice(-4);
  return `•••• ${lastFour}`;
}

function wait(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

// ---------------------------------------------------------------------------
// Decorative dot-grid — echoes the mark's own dotted lettering
// ---------------------------------------------------------------------------

function DotField() {
  const cols = 9;
  const rows = 11;
  const dots = [];
  let id = 0;
  for (let r = 0; r < rows; r += 1) {
    for (let c = 0; c < cols; c += 1) {
      const seed = (r * cols + c) % 7;
      const isCyan = seed !== 0;
      const isPink = seed === 0 && (r + c) % 5 === 0;
      const size = seed === 3 ? 5 : 3.5;
      dots.push({
        id: id++,
        x: (c / (cols - 1)) * 100,
        y: (r / (rows - 1)) * 100,
        color: isPink ? PINK : isCyan ? CYAN : GRAY,
        size,
        delay: ((r + c) % 6) * 0.4,
      });
    }
  }
  return (
    <svg
      className="absolute inset-0 h-full w-full opacity-[0.16]"
      preserveAspectRatio="xMidYMid slice"
      aria-hidden="true"
    >
      {dots.map((d) => (
        <circle
          key={d.id}
          cx={`${d.x}%`}
          cy={`${d.y}%`}
          r={d.size}
          fill={d.color}
          className="ncn-dot"
          style={{ animationDelay: `${d.delay}s` }}
        />
      ))}
    </svg>
  );
}

