// ---------------------------------------------------------------------------
// Progress ledger for the two-step flow
// ---------------------------------------------------------------------------

function StepLedger({ activeStepIndex }) {
  const steps = ["Identify", "Verify"];
  return (
    <ol className="flex items-center gap-3" aria-label="Sign-in progress">
      {steps.map((label, index) => {
        const isComplete = index < activeStepIndex;
        const isActive = index === activeStepIndex;
        return (
          <li key={label} className="flex items-center gap-3">
            <div className="flex items-center gap-2">
              <span
                className="flex h-6 w-6 items-center justify-center rounded-full text-[11px] font-mono font-medium transition-colors"
                style={{
                  backgroundColor: isComplete || isActive ? CYAN : "#EDEDEC",
                  color: isComplete || isActive ? "#ffffff" : GRAY,
                }}
              >
                {isComplete ? <CheckCircle2 className="h-3.5 w-3.5" /> : index + 1}
              </span>
              <span
                className="text-xs font-medium"
                style={{ color: isActive ? "#16211f" : GRAY }}
              >
                {label}
              </span>
            </div>
            {index === 0 && (
              <span
                className="h-px w-8 transition-colors"
                style={{ backgroundColor: isComplete ? CYAN : "#E4E2DD" }}
                aria-hidden="true"
              />
            )}
          </li>
        );
      })}
    </ol>
  );
}

// ---------------------------------------------------------------------------
// Main component
// ---------------------------------------------------------------------------

export default function LoginPage() {
  const [step, setStep] = useState("credentials");
  const [credentials, setCredentials] = useState({ email: "", password: "", userType: "" });
  const [matchedUser, setMatchedUser] = useState(null);

  const [otpValue, setOtpValue] = useState("");
  const [issuedOtp, setIssuedOtp] = useState("");

  const [isSubmittingCredentials, setIsSubmittingCredentials] = useState(false);
  const [isVerifyingOtp, setIsVerifyingOtp] = useState(false);
  const [credentialsError, setCredentialsError] = useState(null);
  const [otpError, setOtpError] = useState(null);
  const [resendCooldown, setResendCooldown] = useState(0);
  const [destination, setDestination] = useState(null);

  useEffect(() => {
    if (resendCooldown <= 0) return;
    const timer = window.setInterval(() => {
      setResendCooldown((previous) => (previous <= 1 ? 0 : previous - 1));
    }, 1000);
    return () => window.clearInterval(timer);
  }, [resendCooldown]);

  const handleCredentialChange = (field, value) => {
    setCredentials((previous) => ({ ...previous, [field]: value }));
    setCredentialsError(null);
  };

  const dispatchOtp = useCallback((user) => {
    const otp = generateDummyOtp();
    setIssuedOtp(otp);
    setResendCooldown(RESEND_COOLDOWN_SECONDS);
    // eslint-disable-next-line no-console
    console.info(`[DEV ONLY] OTP for ${user.email} sent to WhatsApp ${user.whatsappNumber}: ${otp}`);
  }, []);

  const handleRequestOtp = async (event) => {
    event.preventDefault();
    setCredentialsError(null);

    if (!credentials.email || !credentials.password || !credentials.userType) {
      setCredentialsError("Enter your email, password, and user type to continue.");
      return;
    }

    setIsSubmittingCredentials(true);
    await wait(SIMULATED_LATENCY_MS);

    const user = MOCK_USERS.find(
      (candidate) =>
        candidate.email.toLowerCase() === credentials.email.trim().toLowerCase() &&
        candidate.password === credentials.password &&
        candidate.userType === credentials.userType
    );

    setIsSubmittingCredentials(false);

    if (!user) {
      setCredentialsError("Those details don't match a known account. Check the email, password, and user type.");
      return;
    }

    setMatchedUser(user);
    dispatchOtp(user);
    setOtpValue("");
    setOtpError(null);
    setStep("otp");
  };

  const handleResendOtp = () => {
    if (!matchedUser || resendCooldown > 0) return;
    dispatchOtp(matchedUser);
    setOtpValue("");
    setOtpError(null);
  };

  const handleBackToCredentials = () => {
    setStep("credentials");
    setOtpValue("");
    setOtpError(null);
    setMatchedUser(null);
    setIssuedOtp("");
  };

  const handleVerifyOtp = async () => {
    if (!matchedUser) return;

    if (otpValue.length !== OTP_LENGTH) {
      setOtpError(`Enter the full ${OTP_LENGTH}-digit code.`);
      return;
    }

    setIsVerifyingOtp(true);
    await wait(SIMULATED_LATENCY_MS - 150);
    setIsVerifyingOtp(false);

    if (otpValue !== issuedOtp) {
      setOtpError("That code doesn't match. Check WhatsApp and try again.");
      return;
    }

    setDestination({
      fullName: matchedUser.fullName,
      userType: matchedUser.userType,
      route: ROUTE_BY_USER_TYPE[matchedUser.userType],
    });
    setStep("success");
  };

  const activeStepIndex = step === "credentials" ? 0 : 1;

  return (
    <div className="flex min-h-screen w-full bg-[#FAFAF8]">
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=Inter:wght@400;500;600;700&display=swap');
        .ncn-scope { font-family: 'Inter', ui-sans-serif, system-ui, sans-serif; }
        .ncn-dot { animation: ncnPulse 5s ease-in-out infinite; transform-origin: center; }
        @keyframes ncnPulse {
          0%, 100% { opacity: 0.55; transform: scale(1); }
          50% { opacity: 1; transform: scale(1.35); }
        }
        @media (prefers-reduced-motion: reduce) {
          .ncn-dot { animation: none; }
        }
        .ncn-focus:focus-visible {
          outline: 2px solid ${CYAN};
          outline-offset: 2px;
        }
      `}</style>

      <div className="ncn-scope flex min-h-screen w-full">
        <BrandPanel />

        <div className="flex flex-1 flex-col items-center justify-center px-6 py-12 sm:px-10">
          <div className="w-full max-w-sm">
            {/* Mobile wordmark */}
            <div className="mb-8 flex items-center justify-center lg:hidden">
              <img src={LOGO_SRC} alt="NCN Holdings" className="h-14" />
            </div>

            {step !== "success" && (
              <div className="mb-8 flex items-center justify-between">
                <div>
                  <p
                    className="font-mono text-[11px] uppercase tracking-[0.3em]"
                    style={{ color: CYAN }}
                  >
                    NCN ERP
                  </p>
                  <h1
                    className="mt-1 text-[26px] font-semibold text-[#16211f]"
                    style={{ fontFamily: "'Space Grotesk', sans-serif" }}
                  >
                    {step === "credentials" ? "Welcome back" : "Check WhatsApp"}
                  </h1>
                </div>
                <StepLedger activeStepIndex={activeStepIndex} />
              </div>
            )}

            {step === "credentials" && (
              <form onSubmit={handleRequestOtp} className="space-y-5" noValidate>
                <p className="text-sm text-[#5b5b5b]">
                  Sign in to your workspace. We'll text a one-time code to your
                  registered WhatsApp before letting you in.
                </p>

                {credentialsError && (
                  <div
                    className="flex gap-2.5 rounded-lg border-l-4 bg-[#fdf1f6] px-3.5 py-3 text-sm"
                    style={{ borderColor: PINK }}
                    role="alert"
                  >
                    <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" style={{ color: PINK }} />
                    <div>
                      <p className="font-medium text-[#3d1224]">Can't sign in</p>
                      <p className="mt-0.5 text-[#6e4256]">{credentialsError}</p>
                    </div>
                  </div>
                )}

                <div className="space-y-1.5">
                  <Label htmlFor="email" className="text-xs font-medium text-[#3f3f3f]">
                    Email
                  </Label>
                  <div className="relative">
                    <Mail
                      className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2"
                      style={{ color: GRAY }}
                    />
                    <Input
                      id="email"
                      type="email"
                      autoComplete="email"
                      placeholder="you@ncnholdings.lk"
                      value={credentials.email}
                      onChange={(event) => handleCredentialChange("email", event.target.value)}
                      className="ncn-focus h-11 border-[#E4E2DD] pl-9 focus-visible:ring-0"
                    />
                  </div>
                </div>

                <div className="space-y-1.5">
                  <div className="flex items-center justify-between">
                    <Label htmlFor="password" className="text-xs font-medium text-[#3f3f3f]">
                      Password
                    </Label>
                    <button
                      type="button"
                      className="text-xs font-medium hover:underline"
                      style={{ color: PINK }}
                    >
                      Forgot?
                    </button>
                  </div>
                  <div className="relative">
                    <Lock
                      className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2"
                      style={{ color: GRAY }}
                    />
                    <Input
                      id="password"
                      type="password"
                      autoComplete="current-password"
                      placeholder="••••••••"
                      value={credentials.password}
                      onChange={(event) => handleCredentialChange("password", event.target.value)}
                      className="ncn-focus h-11 border-[#E4E2DD] pl-9 focus-visible:ring-0"
                    />
                  </div>
                </div>

                <div className="space-y-1.5">
                  <Label className="text-xs font-medium text-[#3f3f3f]">User type</Label>
                  <div
                    role="radiogroup"
                    aria-label="User type"
                    className="grid grid-cols-3 gap-1.5 rounded-xl border border-[#E4E2DD] bg-[#F5F4F0] p-1.5"
                  >
                    {USER_TYPE_OPTIONS.map((option) => {
                      const isActive = credentials.userType === option.value;
                      return (
                        <button
                          key={option.value}
                          type="button"
                          role="radio"
                          aria-checked={isActive}
                          onClick={() => handleCredentialChange("userType", option.value)}
                          className="ncn-focus flex flex-col items-center gap-0.5 rounded-lg px-2 py-2.5 text-center transition-all"
                          style={{
                            backgroundColor: isActive ? CYAN : "transparent",
                            color: isActive ? "#ffffff" : "#3f3f3f",
                            boxShadow: isActive ? "0 4px 10px rgba(19,170,170,0.25)" : "none",
                          }}
                        >
                          <span className="text-[13px] font-medium">{option.label}</span>
                          <span
                            className="text-[10px] leading-tight"
                            style={{ color: isActive ? "rgba(255,255,255,0.8)" : GRAY }}
                          >
                            {option.helperText}
                          </span>
                        </button>
                      );
                    })}
                  </div>
                </div>

                <Button
                  type="submit"
                  disabled={isSubmittingCredentials}
                  className="ncn-focus h-11 w-full text-sm font-medium text-white hover:opacity-90"
                  style={{ backgroundColor: CYAN }}
                >
                  {isSubmittingCredentials ? (
                    <span className="flex items-center justify-center gap-2">
                      <span className="h-4 w-4 animate-spin rounded-full border-2 border-white/40 border-t-white" />
                      Checking details…
                    </span>
                  ) : (
                    "Send code to WhatsApp"
                  )}
                </Button>

                <div className="rounded-lg border border-dashed border-[#E4E2DD] bg-[#F9F8F5] px-3.5 py-2.5">
                  <p className="text-[11px] leading-relaxed text-[#7a7a7a]">
                    <span className="font-mono font-medium" style={{ color: CYAN }}>
                      Demo
                    </span>{" "}
                    admin@ncnholdings.lk · clerk@ncnholdings.lk · guest@ncnholdings.lk — password
                    shown as the field placeholder pattern.
                  </p>
                </div>
              </form>
            )}

            {step === "otp" && (
              <div className="space-y-6">
                <div className="flex items-start gap-3 rounded-xl bg-[#EEF9F9] px-4 py-3.5">
                  <span
                    className="flex h-9 w-9 shrink-0 items-center justify-center rounded-full"
                    style={{ backgroundColor: CYAN }}
                  >
                    <MessageCircle className="h-4.5 w-4.5 text-white" />
                  </span>
                  <p className="text-sm leading-relaxed text-[#16211f]">
                    We sent a {OTP_LENGTH}-digit code to{" "}
                    <span className="font-medium">
                      {matchedUser ? maskWhatsappNumber(matchedUser.whatsappNumber) : "your number"}
                    </span>{" "}
                    on WhatsApp. It expires shortly.
                  </p>
                </div>

                {otpError && (
                  <div
                    className="flex gap-2.5 rounded-lg border-l-4 bg-[#fdf1f6] px-3.5 py-3 text-sm"
                    style={{ borderColor: PINK }}
                    role="alert"
                  >
                    <AlertCircle className="mt-0.5 h-4 w-4 shrink-0" style={{ color: PINK }} />
                    <div>
                      <p className="font-medium text-[#3d1224]">Code not accepted</p>
                      <p className="mt-0.5 text-[#6e4256]">{otpError}</p>
                    </div>
                  </div>
                )}

                <div className="flex flex-col items-center gap-3">
                  <InputOTP maxLength={OTP_LENGTH} value={otpValue} onChange={setOtpValue}>
                    <InputOTPGroup>
                      {Array.from({ length: OTP_LENGTH }).map((_, index) => (
                        <InputOTPSlot
                          key={index}
                          index={index}
                          className="ncn-focus h-12 w-10 border-[#E4E2DD] font-mono text-base"
                        />
                      ))}
                    </InputOTPGroup>
                  </InputOTP>

                  <button
                    type="button"
                    onClick={handleResendOtp}
                    disabled={resendCooldown > 0}
                    className="text-xs font-mono uppercase tracking-wide underline-offset-4 hover:underline disabled:cursor-not-allowed disabled:no-underline"
                    style={{ color: resendCooldown > 0 ? "#b7b7b7" : PINK }}
                  >
                    {resendCooldown > 0 ? `Resend code in ${resendCooldown}s` : "Resend code"}
                  </button>
                </div>

                <div className="rounded-lg border border-dashed border-[#E4E2DD] bg-[#F9F8F5] px-3.5 py-2.5">
                  <p className="text-[11px] leading-relaxed text-[#7a7a7a]">
                    <span className="font-mono font-medium" style={{ color: CYAN }}>
                      Demo
                    </span>{" "}
                    no real WhatsApp message is sent. The code is logged to the browser
                    console so you can complete the flow.
                  </p>
                </div>

                <div className="space-y-2.5">
                  <Button
                    type="button"
                    onClick={handleVerifyOtp}
                    disabled={isVerifyingOtp}
                    className="ncn-focus h-11 w-full text-sm font-medium text-white hover:opacity-90"
                    style={{ backgroundColor: CYAN }}
                  >
                    {isVerifyingOtp ? (
                      <span className="flex items-center justify-center gap-2">
                        <span className="h-4 w-4 animate-spin rounded-full border-2 border-white/40 border-t-white" />
                        Verifying…
                      </span>
                    ) : (
                      <span className="flex items-center justify-center gap-2">
                        <ShieldCheck className="h-4 w-4" />
                        Verify &amp; continue
                      </span>
                    )}
                  </Button>
                  <Button
                    type="button"
                    variant="ghost"
                    onClick={handleBackToCredentials}
                    className="ncn-focus h-11 w-full text-sm font-medium text-[#5b5b5b] hover:bg-[#F5F4F0]"
                  >
                    <ArrowLeft className="mr-2 h-4 w-4" />
                    Back to details
                  </Button>
                </div>
              </div>
            )}

            {step === "success" && destination && (
              <div className="flex flex-col items-center gap-5 py-6 text-center">
                <span
                  className="flex h-16 w-16 items-center justify-center rounded-full"
                  style={{ backgroundColor: "#E7F7F5" }}
                >
                  <Sparkles className="h-7 w-7" style={{ color: CYAN }} />
                </span>
                <div className="space-y-1.5">
                  <h2
                    className="text-xl font-semibold text-[#16211f]"
                    style={{ fontFamily: "'Space Grotesk', sans-serif" }}
                  >
                    You're verified, {destination.fullName.split(" ")[0]}
                  </h2>
                  <p className="text-sm text-[#7a7a7a]">
                    Taking you to{" "}
                    <span className="font-mono font-medium" style={{ color: CYAN }}>
                      {destination.route}
                    </span>
                  </p>
                </div>
                <div className="h-1 w-40 overflow-hidden rounded-full bg-[#E4E2DD]">
                  <div
                    className="h-full rounded-full"
                    style={{ backgroundColor: CYAN, animation: "ncnBar 1.4s ease-in-out infinite" }}
                  />
                </div>
                <style>{`
                  @keyframes ncnBar {
                    0% { width: 0%; margin-left: 0%; }
                    50% { width: 60%; margin-left: 20%; }
                    100% { width: 0%; margin-left: 100%; }
                  }
                `}</style>
                <button
                  type="button"
                  onClick={handleBackToCredentials}
                  className="text-xs font-medium hover:underline"
                  style={{ color: GRAY }}
                >
                  Not you? Sign in as someone else
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}